use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms: 5,
        max_delay_ms: 12,
    }
}

#[test]
fn public_api_retries_transient_failures_with_bounded_delays() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 | 3 => Err(RetryError::Transient("temporary".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![5, 10, 12]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(3), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
}

